  if(nextView==='buildings'){const[{data:defs,error:de},{data:rows,error:oe}]=await Promise.all([supabase.from('building_definitions').select('id,name,description,base_metal,base_crystal,base_deuterium,base_build_time_seconds,max_level,valid_kinds').order('id'),supabase.from('planet_buildings').select('building_id,level').eq('planet_id',activePlanet.id)]);if(de)throw de;if(oe)throw oe;setDefinitions((defs??[])as Definition[]);setOwned(Object.fromEntries((rows??[]).map((r:{building_id:string;level:number})=>[r.building_id,r.level])));const{data:q}=await supabase.from('building_queue').select('id,building_id,target_level,finishes_at,status,is_downgrade').eq('planet_id',activePlanet.id).in('status',['BUILDING','QUEUED']).order('finishes_at');setQueues((q??[])as QueueRow[]);const{data:bp}=await supabase.rpc('get_planet_building_preview',{p_planet_id:activePlanet.id});setBuildingPreview(Object.fromEntries(((bp??[])as BuildingPreviewRow[]).map(r=>[r.building_id,r])));await syncPlanetState();const infos=await Promise.all((defs??[]).map(async d=>{const{data:i,error:ie}=await supabase.rpc('can_start_building',{p_player_id:currentPlayer.id,p_planet_id:activePlanet.id,p_building_id:d.id});if(ie)throw ie;return[d.id,(i??[])[0]]as const}));setBuildingInfo(Object.fromEntries(infos.filter(([,i])=>Boolean(i)).map(([id,i])=>[id,i])))}
