 useEffect(()=>{if(!activePlanetId||!currentPlayer)return;void(async()=>{const{data,error:e}=await supabase.rpc('get_planet_economy_overview',{p_planet_id:activePlanetId});if(e){console.warn('get_planet_economy_overview',e.message);setEconomy(null);return}setEconomy(((data??[])as EconomyRow[])[0]??null)})()},[activePlanetId,currentPlayer?.id]);
 useEffect(()=>{if(!researchLabStatus?.research_lab_upgrading||!researchLabStatus?.upgrading_finishes_at||!activePlanet||!currentPlayer)return;const delay=Math.max(1000,Math.min(new Date(researchLabStatus.upgrading_finishes_at).getTime()+1500-Date.now(),2147000000));const timer=window.setTimeout(()=>{void loadView(view)},delay);return()=>window.clearTimeout(timer)},[researchLabStatus?.research_lab_upgrading,researchLabStatus?.upgrading_finishes_at,view,activePlanet?.id,currentPlayer?.id]);
