 useEffect(()=>{if(planets.length===0)return;if(selectedBodyId&&planets.some(p=>p.id===selectedBodyId))return;const capital=planets.find(p=>p.is_homeworld)??planets[0];if(selectedBodyId)setNotice(`El cuerpo seleccionado ya no está disponible; se activa ${capital.name} ${coordinates(capital)}.`);saveBody(capital.id);setSelectedBodyId(capital.id)},[planets,selectedBodyId]);
 const title=navItems.find(n=>n.id===view)?.label??'OVERVIEW';
 const getCost=(d:Definition,kind:'building'|'research'|'ship'|'defense')=>({metal:kind==='defense'?d.metal_cost:d.base_metal,crystal:kind==='defense'?d.crystal_cost:d.base_crystal,deuterium:kind==='defense'?d.deuterium_cost:d.base_deuterium});
