 async function cancelQueue(kind:'building'|'research',queueId:string){if(!activePlanet||!currentPlayer)return;setBusyId(queueId);setNotice(null);setError(null);try{if(kind==='building'){const{data,error:e}=await supabase.rpc('cancel_building',{p_queue_id:queueId});if(e)throw e;const row=(data??[])[0];setNotice(row?`${definitionLabel(row.building_id)}: cola cancelada en el nivel ${row.target_level}. Reembolso ${formatNumber(row.refund_metal)} M / ${formatNumber(row.refund_crystal)} C / ${formatNumber(row.refund_deuterium)} D.`:'Cola de edificio cancelada.')}else{const{data,error:e}=await supabase.rpc('cancel_research',{p_queue_id:queueId});if(e)throw e;const row=(data??[])[0];setNotice(row?`${definitionLabel(row.research_id)}: investigación cancelada en el nivel ${row.target_level}. Reembolso ${formatNumber(row.refund_metal)} M / ${formatNumber(row.refund_crystal)} C / ${formatNumber(row.refund_deuterium)} D.`:'Investigación cancelada.')}await refreshPlanet();await loadView(view)}catch(err){setError(err instanceof Error?err.message:'No se pudo cancelar la cola.')}finally{setBusyId(null)}}
